#include <iostream>

// Custom non-parameterized manipulator emitting a horizontal tab
std::ostream& tab(std::ostream& output) {
    return output << '\t';
}

// Custom manipulator emitting a simulated endline with flush
std::ostream& endLine(std::ostream& output) {
    return output << '\n' << std::flush;
}

// Custom manipulator writing bracketed delimiters
std::ostream& bracket(std::ostream& output) {
    return output << " | ";
}

int main() {
    std::cout << "Testing custom tab manipulator:" << endLine;
    std::cout << 'a' << tab << 'b' << tab << 'c' << endLine;

    std::cout << "Testing bracket manipulator:" << endLine;
    std::cout << 100 << bracket << 200 << bracket << 300 << endLine;

    return 0;
}

#include <iostream>

int main() {
    const double val1 = 9.9900;
    const double val2 = 9.9000;
    const double val3 = 9.0000;

    std::cout << "Before using showpoint:\n";
    std::cout << "val1: " << val1 << '\n';
    std::cout << "val2: " << val2 << '\n';
    std::cout << "val3: " << val3 << '\n';

    std::cout << "\nAfter using showpoint:\n";
    std::cout << std::showpoint;
    std::cout << "val1: " << val1 << '\n';
    std::cout << "val2: " << val2 << '\n';
    std::cout << "val3: " << val3 << '\n';

    std::cout << "\nAfter using noshowpoint:\n";
    std::cout << std::noshowpoint;
    std::cout << "val3: " << val3 << '\n';

    return 0;
}

#include <iostream>
#include <iomanip>

int main() {
    int val = 12345;

    std::cout << "Default right justification (setw 10):\n";
    std::cout << std::setw(10) << val << '\n';

    std::cout << "Left justification (setw 10):\n";
    std::cout << std::left << std::setw(10) << val << '\n';

    std::cout << "Right justification again (setw 10):\n";
    std::cout << std::right << std::setw(10) << val << '\n';

    std::cout << "Internal justification with showpos (setw 10):\n";
    std::cout << std::internal << std::showpos << std::setw(10) << 123 << '\n';

    // Reset showpos and internal alignment
    std::cout << std::noshowpos << std::right;
    return 0;
}
